package com.example.library.application.loan;

import com.example.library.domain.loan.Isbn;
import com.example.library.domain.loan.Loan;
import com.example.library.domain.loan.LoanId;
import com.example.library.domain.loan.LoanRepository;
import com.example.library.domain.loan.MemberId;
import java.time.Clock;

public final class BorrowBook {
    private final LoanRepository loans;
    private final Clock clock;

    public BorrowBook(LoanRepository loans, Clock clock) {
        this.loans = loans;
        this.clock = clock;
    }

    public void execute(LoanId id, MemberId memberId, Isbn isbn) {
        Loan loan = Loan.borrow(id, memberId, isbn, clock.instant(),
                loans.countByMember(memberId), loans.existsByIsbn(isbn));
        loans.save(loan);
    }
}
