package com.example.library.api.loan;

import com.example.library.application.loan.BorrowBook;
import com.example.library.domain.loan.Isbn;
import com.example.library.domain.loan.LoanId;
import com.example.library.domain.loan.MemberId;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
class LoanController {
    record BorrowRequest(String memberId, String isbn) {
    }

    record BorrowResponse(UUID loanId) {
    }

    private final BorrowBook borrowBook;

    LoanController(BorrowBook borrowBook) {
        this.borrowBook = borrowBook;
    }

    @PostMapping("/loans")
    @ResponseStatus(HttpStatus.CREATED)
    @Transactional
    BorrowResponse borrow(@RequestBody BorrowRequest request) {
        LoanId id = new LoanId(UUID.randomUUID());
        borrowBook.execute(id, new MemberId(request.memberId()), new Isbn(request.isbn()));
        return new BorrowResponse(id.value());
    }
}
